pub fn obj2sctype(rep: NumpyObject, default: Option<NumpyScalarType>) -> Option<NumpyScalarType> {
    match rep {
        NumpyObject::Int(_) | NumpyObject::IntArray(_) => Some(NumpyScalarType::Int64),
        NumpyObject::Float(_) | NumpyObject::FloatArray(_) => Some(NumpyScalarType::Float64),
        NumpyObject::ComplexArray(_) => Some(NumpyScalarType::Complex128),
        NumpyObject::String(_) => Some(NumpyScalarType::String),
        NumpyObject::Bool(_) => Some(NumpyScalarType::Bool),
        NumpyObject::Object => default,
    }
}